declare(strict_types=1);
namespace Sexogate;
final class Purchasing
{
    public function __construct(private Database $db,private Config $config){}
    public function create(string $supplier,string $currency,array $items,string $reference,string $key,Principal $actor):array
    {$actor->require('catalog',true);RuleViolation::ensure(in_array($currency,['TRY','EUR','USD','GBP'],true)&&count($items)>0&&count($items)<=100&&mb_strlen(trim($reference))>=5,'PURCHASE_INVALID','Satın alma alanlarını kontrol edin.',400);usort($items,fn($a,$b)=>strcmp($a['variantId']??'',$b['variantId']??''));return (new Audit($this->db))->command($actor,$key,['purchase-create',$supplier,$currency,$items,$reference],function()use($supplier,$currency,$items,$reference,$actor){RuleViolation::ensure($this->db->one('SELECT id FROM suppliers WHERE id=? AND archived=false FOR SHARE',[$supplier]),'SUPPLIER_NOT_FOUND','Etkin tedarikçi gerekir.');$id=Database::id();$this->db->execute('INSERT INTO purchase_orders(id,supplier_id,currency,reference) VALUES(?,?,?,?)',[$id,$supplier,$currency,$reference]);$seen=[];$totals=[];foreach($items as $item){$v=$item['variantId']??'';$q=$item['quantity']??0;$cost=Money::amount($item['unitCostMinor']??null);RuleViolation::ensure(!isset($seen[$v])&&is_int($q)&&$q>0&&$q<=1000000&&$this->db->one('SELECT id FROM variants WHERE id=? AND active=true FOR SHARE',[$v])&&!$this->db->one('SELECT bundle_variant_id FROM bundle_components WHERE bundle_variant_id=?',[$v]),'PURCHASE_ITEM_INVALID','Satın alma yalnız tekil fiziksel stok kodları için açılabilir.');$seen[$v]=true;$totals[]=Money::multiply($cost,$q);$this->db->execute('INSERT INTO purchase_items(purchase_id,variant_id,quantity,unit_cost_minor) VALUES(?,?,?,?)',[$id,$v,$q,$cost]);}Money::sum($totals);(new Audit($this->db))->record($actor,'create','purchase_orders',$id);return ['id'=>$id,'status'=>'ordered'];});}
    public function receive(string $purchase,array $items,string $reference,string $key,Principal $actor):array
    {$actor->require('inventory',true);RuleViolation::ensure(count($items)>0&&count($items)<=100&&mb_strlen(trim($reference))>=5,'RECEIPT_INVALID','Kabul satırları ve belge referansı gerekir.',400);usort($items,fn($a,$b)=>strcmp($a['variantId']??'',$b['variantId']??''));return (new Audit($this->db))->command($actor,$key,['purchase-receive',$purchase,$items,$reference],function()use($purchase,$items,$reference,$actor){(new Inventory($this->db,$this->config))->definition('bundle-definition');$po=$this->db->one('SELECT status FROM purchase_orders WHERE id=? FOR UPDATE',[$purchase]);RuleViolation::ensure($po&&in_array($po['status'],['ordered','partially_received'],true),'PURCHASE_STATE','Satın alma mal kabulüne uygun değil.');$receipt=Database::id();$this->db->execute('INSERT INTO purchase_receipts(id,purchase_id,reference,actor_id) VALUES(?,?,?,?)',[$receipt,$purchase,$reference,$actor->id]);$seen=[];foreach($items as $item){$v=$item['variantId']??'';$q=$item['quantity']??0;$line=$this->db->one('SELECT quantity,received FROM purchase_items WHERE purchase_id=? AND variant_id=? FOR UPDATE',[$purchase,$v]);RuleViolation::ensure(!isset($seen[$v])&&is_int($q)&&$q>0&&$q<=1000000&&$line&&(int)$line['received']+$q<=(int)$line['quantity'],'RECEIPT_QUANTITY','Kabul, kalan sipariş miktarını aşamaz veya satırlar tekrarlanamaz.');$seen[$v]=true;$accepted=(new InventoryManagement($this->db,$this->config))->accept($v,$q,$item,$reference,$receipt,$actor);$this->db->execute('INSERT INTO purchase_receipt_items(id,receipt_id,variant_id,lot_id,quantity,quarantined,movement_id) VALUES(?,?,?,?,?,?,?)',[Database::id(),$receipt,$v,$accepted['lotId'],$q,(int)$accepted['quarantined'],$accepted['movementId']]);$this->db->execute('UPDATE purchase_items SET received=received+? WHERE purchase_id=? AND variant_id=?',[$q,$purchase,$v]);}$left=(int)$this->db->one('SELECT COUNT(*) n FROM purchase_items WHERE purchase_id=? AND received<quantity',[$purchase])['n'];$status=$left>0?'partially_received':'received';$this->db->execute('UPDATE purchase_orders SET status=? WHERE id=?',[$status,$purchase]);(new Audit($this->db))->record($actor,'receive','purchase_orders',$purchase);return ['id'=>$receipt,'status'=>$status];});}
    public function listing(Principal $actor):array
    {$actor->require('purchases');$rows=$this->db->all('SELECT p.id,p.status,p.currency,p.reference,p.created_at,s.name supplier FROM purchase_orders p JOIN suppliers s ON s.id=p.supplier_id ORDER BY p.created_at DESC LIMIT 50');foreach($rows as &$r)$r['items']=$this->db->all('SELECT i.variant_id,v.sku,i.quantity,i.received,v.lot_tracking,v.expiry_required'.($actor->costs()?',i.unit_cost_minor':'').' FROM purchase_items i JOIN variants v ON v.id=i.variant_id WHERE i.purchase_id=? ORDER BY v.sku',[$r['id']]);return $rows;}
}
